//! JSON-RPC dispatch for the WebDAV adapter.
//!
//! `fs.*` is generated by `#[fiex_sdk::filesystem]`; only connection lifecycle
//! methods stay manual.
use super::fs;
use fiex_plugin_sdk::{self as sdk, RpcError};
use serde_json::Value;

pub(crate) fn dispatch(ctx: sdk::RequestContext) -> Result<Value, RpcError> {
    match ctx.method() {
        "connection.open" => {
            let mount = ctx.params()["mountId"]
                .as_str()
                .ok_or_else(|| RpcError::invalid_params("missing mountId"))?;
            Ok(
                serde_json::json!({"kind":"vfs","mountId":mount,"nodeRef":{"mountId":mount,"nodeId":""}}),
            )
        }
        "connection.validate" => fs::validate(&ctx),
        method => Err(RpcError::method_not_found(method)),
    }
}
